actions.script:
const names = ['primary', 'secondary', 'accent', 'info', 'warning', 'positive', 'negative']
const shades = ['#1565c0', '#00796b', '#6a1b9a', '#ef6c00', '#2e7d32']
const list = Array.from(series || []).map((one) => (one && one.getMap ? one.getMap() : one) || {})
const labelList = Array.from(labels || []).map((label) => label == null ? '' : String(label))
const colorOf = (i) => i < names.length ? 'cv(' + JSON.stringify(names[i]) + ')' : JSON.stringify(shades[(i - names.length) % shades.length])
const hasY2 = list.some((one) => one.axis === 'y2')
const datasets = list.map((one, i) => {
    const kind = one.kind || type
    const data = Array.from(one.data || []).map((value) => value == null || value === '' ? null : Number(String(value)))
    const parts = ['label: ' + JSON.stringify(String(one.name == null ? '' : one.name)), 'data: ' + JSON.stringify(data),
        'borderColor: ' + colorOf(i), 'backgroundColor: ' + colorOf(i), 'type: ' + JSON.stringify(kind)]
    if (kind === 'line') parts.push('tension: 0', 'pointRadius: 3', 'fill: false', 'spanGaps: true')
    if (one.dashed) parts.push('borderDash: [6, 4]', 'borderWidth: 1', 'pointRadius: 0')
    if (one.axis === 'y2') parts.push('yAxisID: "y2"')
    if (kind === 'bar') parts.push('maxBarThickness: 40', 'borderRadius: 2')
    return '{' + parts.join(', ') + '}'
})
const valueAxis = horizontal ? 'x' : 'y'
const categoryAxis = horizontal ? 'y' : 'x'
const tick = percent ? ', callback: (value) => value + "%"' : ''
const titleOf = (text) => text ? ', title: {display: true, text: ' + JSON.stringify(String(text)) + ', color: tc}' : ''
const scales = [categoryAxis + ': {stacked: ' + !!stacked + ', ticks: {color: tc, autoSkip: true, maxRotation: 0}, grid: {display: false}}',
    valueAxis + ': {stacked: ' + !!stacked + ', beginAtZero: true, ticks: {color: tc' + tick + '}, grid: {color: gc}' + titleOf(yTitle) + '}']
if (hasY2) scales.push('y2: {position: "right", beginAtZero: true, ticks: {color: tc}, grid: {display: false}' + titleOf(y2Title) + '}')
const expression = '((cv, tc, gc) => ({type: ' + JSON.stringify(type === 'line' ? 'line' : 'bar') + ', data: {labels: ' + JSON.stringify(labelList)
    + ', datasets: [' + datasets.join(', ') + ']}, options: {maintainAspectRatio: false, animation: false' + (horizontal ? ', indexAxis: "y"' : '')
    + ', plugins: {legend: {display: ' + (list.length > 1) + ', position: "bottom", labels: {color: tc, boxWidth: 12}}}, scales: {' + scales.join(', ') + '}}}))('
    + '(name) => (c) => c.chart.canvas.ownerDocument.defaultView.getComputedStyle(c.chart.canvas).getPropertyValue("--q-" + name).trim(), '
    + '(c) => c.chart.canvas.ownerDocument.defaultView.getComputedStyle(c.chart.canvas).color, '
    + '(c) => c.chart.canvas.ownerDocument.defaultView.getComputedStyle(c.chart.canvas).color.replace(/^rgba?\\((\\d+,\\s*\\d+,\\s*\\d+)[^)]*\\)$/, "rgba($1, 0.12)"))'
// for a single-quoted attribute: the text's single quotes, ampersands and less-thans as entities, which the template parser turns back
config = expression.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/'/g, '&#39;')
const safeHeight = /^\d+(px|rem|em|vh)$/.test(String(height || '')) ? String(height) : '260px'
html = '<m-chart height="' + safeHeight + '" :config=\'' + config + '\'></m-chart>'
tui = {t: 'component', id: id, name: 'chart', props: {labels: labelList,
    series: list.map((one) => ({name: String(one.name == null ? '' : one.name), data: Array.from(one.data || []).map((value) => value == null || value === '' ? 0 : Number(String(value)))}))}}

projectOptions = []; programOptions = []; clientOptions = []; managerOptions = []; personOptions = []; workTypeOptions = []; typeOptions = []
managesMoney = !!ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('TIME_ENTRY_RATE'))
const byLabel = (a, b) => String(a.label).localeCompare(String(b.label))
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const visible = Array.from(vis.visibleProjectIds || [])
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (vis.allProjects || visible.length) {
        let find = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetProject')
        if (!vis.allProjects) find = find.condition('workEffortId', 'in', visible)
        if (!includeClosed) find = find.condition('statusId', 'not-in', ['WeClosed', 'WeCancelled'])
        const projects = Array.from(find.selectField('workEffortId').selectField('workEffortName').selectField('parentWorkEffortId').selectField('isTemplate')
                .selectField('statusId').limit(2000).list()).filter((row) => row.isTemplate !== 'Y' && row.statusId !== 'WeCancelled')
        const ids = projects.map((row) => row.workEffortId)
        const names = {}
        for (const row of projects) names[row.workEffortId] = row.workEffortName || row.workEffortId
        projectOptions = projects.map((row) => ({value: row.workEffortId, label: names[row.workEffortId] + ' (' + row.workEffortId + ')'})).sort(byLabel)
        const parents = new Set(projects.map((row) => row.parentWorkEffortId).filter((id) => id && names[id]))
        programOptions = Array.from(parents).map((id) => ({value: id, label: names[id] + ' (' + id + ')'})).sort(byLabel)
        const partyNames = {}
        const partyName = (id) => {
            if (!(id in partyNames)) {
                const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
                partyNames[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
            }
            return partyNames[id]
        }
        const clients = new Set(), managers = new Set(), people = new Set()
        const outside = ['Customer', 'CustomerBillTo', 'ClientManager', 'ClientBilling', 'Vendor', 'VendorBillFrom', 'OrgTeam']
        if (ids.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', ids)
                .conditionDate('fromDate', 'thruDate', null).selectField('partyId').selectField('roleTypeId').list()) {
            if (row.roleTypeId === 'Customer' || row.roleTypeId === 'CustomerBillTo') clients.add(row.partyId)
            else if (!outside.includes(row.roleTypeId)) {
                people.add(row.partyId)
                if (row.roleTypeId === 'ProjectManager' || row.roleTypeId === 'Manager') managers.add(row.partyId)
            }
        }
        const persons = people.size ? new Set(Array.from(ec.entity.find('mantle.party.Person').condition('partyId', 'in', Array.from(people))
                .selectField('partyId').list()).map((row) => row.partyId)) : new Set()
        clientOptions = Array.from(clients).map((id) => ({value: id, label: partyName(id)})).sort(byLabel)
        managerOptions = Array.from(managers).filter((id) => persons.has(id)).map((id) => ({value: id, label: partyName(id)})).sort(byLabel)
        personOptions = Array.from(people).filter((id) => persons.has(id)).map((id) => ({value: id, label: partyName(id)})).sort(byLabel)
    }
    workTypeOptions = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkType').useCache(true).list())
            .map((row) => ({value: row.enumId, label: row.description || row.enumId})).sort(byLabel)
    const purposes = ['WepTask', 'WepFix', 'WepNewFeature', 'WepFeatureEnhance', 'WepFeatureTest', 'WepToDo', 'WepDocument']
    typeOptions = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumId', 'in', purposes).useCache(true).list())
            .map((row) => ({value: row.enumId, label: row.description || row.enumId})).sort(byLabel)
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
